import app from 'flarum/forum/app';

/** A person as the server snapshots them (World::snapshot). */

/** One event from the log (Events::present). */

export const t = (key, params = {}) => app.translator.trans('ernestdefoe-hangout.forum.' + key, params);
export const tt = (key, params = {}) => {
  const out = t(key, params);
  return Array.isArray(out) ? out.join('') : String(out);
};
export function call(method, path, body) {
  let url = app.forum.attribute('apiUrl') + '/hangout' + path;
  if (method === 'GET' && body) url += '?' + new URLSearchParams(body);
  return app.request({
    method,
    url,
    body: method === 'POST' ? body : undefined,
    background: true,
    errorHandler: () => {}
  });
}

/** The sentence for a refusal from the server. */
export function errorText(e) {
  const err = e?.response?.errors?.[0];
  const code = String(err?.code || '').replace(/^hangout_/, '');
  if (code && app.translator.translations['ernestdefoe-hangout.forum.errors.' + code]) return tt('errors.' + code, err.meta || {});
  if (e?.status === 403 || code === 'permission_denied') return tt('errors.permission_denied');
  return tt('errors.generic');
}

/** "4m", "2h", "now": TCZ-style idle times. */
export function idle(seconds) {
  if (seconds < 60) return tt('idle.now');
  if (seconds < 3600) return tt('idle.m', {
    n: Math.floor(seconds / 60)
  });
  if (seconds < 86400) return tt('idle.h', {
    n: Math.floor(seconds / 3600)
  });
  return tt('idle.d', {
    n: Math.floor(seconds / 86400)
  });
}
export function duration(seconds) {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor(seconds % 3600 / 60);
  return h ? tt('duration.hm', {
    h,
    m
  }) : tt('duration.m', {
    m
  });
}

/** Prefix, name and suffix, as on TCZ's who list. */
export function fullName(p) {
  return [p.pf, p.n, p.sf].filter(Boolean).join(' ');
}
flarum.reg.add('ernestdefoe-hangout', 'forum/world/api', { t: t,tt: tt,call: call,errorText: errorText,idle: idle,duration: duration,fullName: fullName, });